def gen(rng):
    def fmt(bal, ops):
        lines = [str(len(bal)), ' '.join(map(str, bal)), str(len(ops))]
        lines += [' '.join(map(str, o)) for o in ops]
        return '\n'.join(lines)

    def rand_op(n, maxm, wide):
        t = rng.choice(['transfer', 'deposit', 'withdraw'])
        hi = n + 2 if wide else n
        if t == 'transfer':
            return ('transfer', rng.randint(1, hi), rng.randint(1, hi), rng.randint(0, maxm))
        return (t, rng.randint(1, hi), rng.randint(0, maxm))

    tests = [
        fmt([0], [('withdraw', 1, 0)]),
        fmt([5], [('transfer', 1, 1, 5), ('transfer', 1, 1, 6), ('deposit', 2, 1), ('withdraw', 1, 5), ('withdraw', 1, 1)]),
        fmt([10, 0], [('transfer', 1, 2, 10), ('transfer', 2, 1, 10), ('transfer', 1, 2, 1), ('transfer', 0, 2, 0)]),
        fmt([10**9] * 3, [('deposit', 3, 10**9), ('transfer', 3, 1, 2 * 10**9), ('withdraw', 1, 3 * 10**9), ('withdraw', 1, 1)]),
    ]
    for _ in range(14):
        n = rng.randint(1, 6)
        bal = [rng.randint(0, 20) for _ in range(n)]
        ops = [rand_op(n, 20, rng.random() < 0.6) for _ in range(rng.randint(1, 10))]
        tests.append(fmt(bal, ops))
    n = 50000
    bal = [rng.randint(0, 10**9) for _ in range(n)]
    tests.append(fmt(bal, [rand_op(n, 10**9, True) for _ in range(50000)]))
    bal = [rng.randint(0, 1000) for _ in range(n)]
    tests.append(fmt(bal, [rand_op(n, 3000, True) for _ in range(50000)]))
    ops = []
    for i in range(50000):
        t = i % 3
        if t == 0:
            ops.append(('deposit', 1, 10**9))
        elif t == 1:
            ops.append(('transfer', 1, 2, rng.randint(0, 10**9)))
        else:
            ops.append(('withdraw', 2, rng.randint(0, 10**9)))
    tests.append(fmt([0] * n, ops))
    return tests
